fn frame(t: i32) {
    host::display::clear(0x101014);
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut hdl: i32 = host::display::state_get(1);
    let mut have: i32 = host::display::state_get(2);
    if down == 1 && prev == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if py >= 20 && py < 70 {
            if px >= 20 && px < 140 && have == 0 {
                hdl = host::compose::spawn_module("visualizer", 60, 120, 384, 288);
                have = 1;
            }
            if px >= 160 && px < 280 && have == 1 {
                host::compose::close_module(hdl);
                have = 0;
            }
        }
    }
    host::display::state_set(0, down);
    host::display::state_set(1, hdl);
    host::display::state_set(2, have);
    let mut oc: i32 = 0x204020;
    if have == 1 { oc = 0x182018; }
    let mut cc: i32 = 0x402020;
    if have == 0 { cc = 0x201818; }
    host::display::fill_rect(20, 20, 120, 50, oc);
    host::display::fill_rect(160, 20, 120, 50, cc);
    host::display::draw_string(36, 38, "OPEN", 0xffffff, 2);
    host::display::draw_string(176, 38, "CLOSE", 0xffffff, 2);
    if have == 1 {
        let st: i32 = host::compose::status(hdl);
        if st == 0 { host::display::draw_string(60, 100, "LOADING...", 0xffff00, 1); }
        if st == 2 { host::display::draw_string(60, 100, "EMBED FAILED", 0xff0000, 1); }
    }
    host::display::draw_string(300, 38, "LIVE:", 0x808080, 1);
    host::display::draw_number(340, 38, host::compose::module_count(), 0x808080, 1);
    host::display::present();
}
